/**
 * mxGraph compatibility layer for the vendored draw.io shape libraries (src/drawio-shapes/vendor,
 * generated by scripts/drawio-palettes/vendor-shapes.ts from jgraph/drawio v32.4.1, Apache-2.0).
 *
 * The upstream files are ES5 scripts written against mxGraph: `function S() { mxShape.call(this); }`,
 * `mxUtils.extend(S, mxShape)`, `S.prototype.paintVertexShape = ...`,
 * `mxCellRenderer.registerShape(name, S)`, `Graph.handleFactory[name] = ...`. This module maps
 * those names onto @maxgraph/core 0.10.3:
 * - mxShape, mxActor, mxCylinder, ... are callable ES5 wrappers around the maxGraph classes (or
 *   the draw.io ports the app registered under the same name): `Base.call(this)` copies the fields
 *   a fresh instance gets, except those the upstream prototypes define (their defaults win, as
 *   prototype properties do in mxGraph); `new Base()` builds a real instance;
 * - `strokewidth` (mxGraph) reads/writes maxGraph's `strokeWidth`;
 * - mxUtils/mxConstants are the subsets the files use (values from mxConstants.js, generated);
 * - registerShape never replaces a shape the app registered itself (hand ports win);
 * - Graph.handleFactory entries are handed to the draw.io handle registry (handles/install.ts).
 */
/* eslint-disable @typescript-eslint/no-explicit-any */
import {
  ActorShape,
  ArrowConnectorShape,
  ArrowShape,
  CellRenderer,
  CloudShape,
  ConnectionConstraint,
  ConnectorShape,
  CylinderShape,
  DoubleEllipseShape,
  EdgeStyle,
  EllipseShape,
  GraphDataModel,
  HexagonShape,
  ImageShape,
  LabelShape,
  LineShape,
  MarkerShape,
  Perimeter,
  Point,
  PolylineShape,
  Rectangle,
  RectangleShape,
  RhombusShape,
  Shape,
  StencilShape,
  StencilShapeRegistry,
  StyleRegistry,
  SwimlaneShape,
  TextShape,
  TriangleShape,
  mathUtils,
  styleUtils,
} from '@maxgraph/core';
import { sanitizeHtmlLabel } from '../engine/html-labels';
import { createHandleFn } from '../handles/create-handle';
import { registerDrawioHandleFactory } from '../handles/install';
import {
  ACTOR_CONSTRAINTS,
  CYLINDER_CONSTRAINTS,
  ELLIPSE_CONSTRAINTS,
  HEXAGON_CONSTRAINTS,
  RECTANGLE_CONSTRAINTS,
} from '../js/shapes-core/util';
import MX_CONSTANTS from '../vendor/mx-constants.json';

type Ctor = new (...args: any[]) => any;

const WRAPPED = new WeakMap<object, any>();

/** True for an ES class constructor (cannot be invoked with `.call`). */
function isClass(fn: unknown): fn is Ctor {
  return typeof fn === 'function' && /^class[\s{]/.test(Function.prototype.toString.call(fn));
}

/** Copies the fields of a fresh instance that the target does not define (own or inherited). */
function initFrom(target: any, template: any): void {
  for (const key of Object.keys(template)) {
    if (!(key in target)) target[key] = template[key];
  }
}

/**
 * ES5-callable stand-in for an ES class: `W.call(this, ...)` initialises an object whose
 * prototype chain includes `Cls.prototype`; `new W(...)` constructs a real instance.
 */
export function es5Wrap(Cls: Ctor, extras?: Record<string, unknown>): any {
  if (!isClass(Cls)) return Cls;
  const cached = WRAPPED.get(Cls);
  if (cached && !extras) return cached;
  const W = function (this: any, ...args: any[]) {
    if (new.target) return Reflect.construct(Cls, args, new.target);
    initFrom(this, Reflect.construct(Cls, args));
    return undefined;
  } as unknown as { prototype: any };
  W.prototype = Object.create(Cls.prototype);
  Object.defineProperty(W.prototype, 'constructor', { value: W, writable: true, configurable: true });
  // ported draw.io classes keep cst/customProperties static; draw.io reads them from the prototype
  const statics = Cls as unknown as Record<string, unknown>;
  for (const key of ['cst', 'customProperties']) {
    if (statics[key] !== undefined && W.prototype[key] === undefined) W.prototype[key] = statics[key];
  }
  if (extras) Object.assign(W.prototype, extras);
  if (!extras) WRAPPED.set(Cls, W);
  return W;
}

/** mxShape.prototype.strokewidth (mxGraph) <-> Shape.strokeWidth (maxGraph). */
function installStrokewidthAlias(): void {
  const proto = Shape.prototype as any;
  if (Object.getOwnPropertyDescriptor(proto, 'strokewidth')) return;
  Object.defineProperty(proto, 'strokewidth', {
    get(this: Shape) { return this.strokeWidth; },
    set(this: Shape, v: number) { this.strokeWidth = v; },
    configurable: true,
  });
  // mxGraphModel.getParent (mxGraph API used by shapes/rack/mxRack.js); maxGraph cells know their parent
  const modelProto = GraphDataModel.prototype as any;
  if (typeof modelProto.getParent !== 'function') {
    modelProto.getParent = (cell: { getParent?: () => unknown } | null) => (cell?.getParent ? cell.getParent() : null);
  }
  // mxShape.getFlowAnimationPath (draw.io flow animation): not supported here
  if (typeof proto.getFlowAnimationPath !== 'function') proto.getFlowAnimationPath = () => null;
}

function registered(name: string, fallback: Ctor): Ctor {
  const shapes = CellRenderer.defaultShapes as unknown as Record<string, Ctor>;
  return Object.prototype.hasOwnProperty.call(shapes, name) ? shapes[name] : fallback;
}

/** mxUtils (the parts the shape libraries use). Ported from mxgraph/src/util/mxUtils.js. */
const mxUtils = {
  getValue(array: any, key: string, defaultValue?: unknown): any {
    const value = array != null ? array[key] : null;
    return value != null ? value : defaultValue;
  },
  getNumber(array: any, key: string, defaultValue: number): number {
    let value = array != null ? array[key] : null;
    if (value == null) value = defaultValue || 0;
    return Number(value);
  },
  getColorValue(array: any, key: string, defaultValue?: unknown): any {
    let value = array != null ? array[key] : null;
    if (value == null || value === 'default') value = defaultValue;
    return value;
  },
  extend(ctor: any, superCtor: any): void {
    const sup = isClass(superCtor) ? es5Wrap(superCtor) : superCtor;
    const f = function () { /* prototype carrier */ } as unknown as { prototype: unknown; new(): object };
    f.prototype = sup.prototype;
    ctor.prototype = new f();
    ctor.prototype.constructor = ctor;
  },
  clone(obj: any, transients?: string[] | null, shallow = false): any {
    if (obj == null || typeof obj !== 'object') return null;
    if (typeof Element !== 'undefined' && obj instanceof Element) return obj.cloneNode(!shallow);
    const clone: any = Array.isArray(obj) ? [] : Object.create(Object.getPrototypeOf(obj));
    for (const i in obj) {
      if (transients != null && transients.indexOf(i) >= 0) continue;
      clone[i] = !shallow && obj[i] != null && typeof obj[i] === 'object' ? mxUtils.clone(obj[i]) : obj[i];
    }
    return clone;
  },
  parseColorList(colorString: string): string[] {
    const tokenizer = /var\([^)]+\)|light-dark\([^)]+\)|(?:rgba?|hsla?|hwb|lab|lch|color)\([^)]+\)|#[0-9a-f]{3,8}|[a-z-]+/gi;
    const matches = colorString.match(tokenizer);
    if (!matches) return colorString.trim() !== '' ? [colorString.trim()] : [];
    return matches;
  },
  rectangleIntersectsSegment: (bounds: Rectangle, p1: Point, p2: Point): boolean =>
    mathUtils.rectangleIntersectsSegment(bounds, p1, p2),
  safeDecodeURIComponent(value: string): string {
    try { return decodeURIComponent(value); } catch { return value; }
  },
  toRadians: (deg: number): number => mathUtils.toRadians(deg),
  getSizeForString: (text: string, fontSize?: number, fontFamily?: string, textWidth?: number | null, fontStyle?: number | null) =>
    styleUtils.getSizeForString(text, fontSize, fontFamily, textWidth, fontStyle),
  indexOf: (array: unknown[] | null, obj: unknown): number => (array != null ? array.indexOf(obj) : -1),
  bind: (scope: unknown, funct: (...a: unknown[]) => unknown) => (...a: unknown[]) => funct.apply(scope, a),
};

/** Graph.scopeHtmlStyles: draw.io scopes <style> elements; here they are dropped (safer, same look for labels). */
function scopeHtmlStyles(html: string | null): string | null {
  return html != null ? html.replace(/<style\b[\s\S]*?<\/style\s*>/gi, '') : html;
}

let shim: Record<string, any> | null = null;
/** Shape names the app registered itself (hand ports); vendored modules never replace them. */
let appShapes: Set<string> | null = null;
const published = new Map<string, unknown>();

/** The `mx` object passed to every vendored module's install(mx). */
export function getMxShim(): Record<string, any> {
  if (shim) return shim;
  installStrokewidthAlias();
  appShapes = new Set(Object.keys(CellRenderer.defaultShapes));
  const handleFactory: Record<string, unknown> = {};
  shim = {
    mxShape: es5Wrap(Shape as unknown as Ctor),
    mxActor: es5Wrap(registered('actor', ActorShape as unknown as Ctor), { constraints: ACTOR_CONSTRAINTS }),
    mxCylinder: es5Wrap(registered('cylinder', CylinderShape as unknown as Ctor), { constraints: CYLINDER_CONSTRAINTS }),
    mxRectangleShape: es5Wrap(registered('rectangle', RectangleShape as unknown as Ctor), { constraints: RECTANGLE_CONSTRAINTS }),
    mxEllipse: es5Wrap(registered('ellipse', EllipseShape as unknown as Ctor), { constraints: ELLIPSE_CONSTRAINTS }),
    mxRhombus: es5Wrap(registered('rhombus', RhombusShape as unknown as Ctor)),
    mxTriangle: es5Wrap(registered('triangle', TriangleShape as unknown as Ctor)),
    mxHexagon: es5Wrap(HexagonShape as unknown as Ctor, { constraints: HEXAGON_CONSTRAINTS }),
    mxCloud: es5Wrap(registered('cloud', CloudShape as unknown as Ctor)),
    mxLine: es5Wrap(registered('line', LineShape as unknown as Ctor)),
    mxImageShape: es5Wrap(registered('image', ImageShape as unknown as Ctor)),
    mxLabel: es5Wrap(registered('label', LabelShape as unknown as Ctor)),
    mxSwimlane: es5Wrap(registered('swimlane', SwimlaneShape as unknown as Ctor)),
    mxArrow: es5Wrap(ArrowShape as unknown as Ctor),
    mxArrowConnector: es5Wrap(ArrowConnectorShape as unknown as Ctor),
    mxConnector: es5Wrap(registered('connector', ConnectorShape as unknown as Ctor)),
    mxPolyline: es5Wrap(PolylineShape as unknown as Ctor),
    mxDoubleEllipse: es5Wrap(registered('doubleEllipse', DoubleEllipseShape as unknown as Ctor)),
    mxText: es5Wrap(TextShape as unknown as Ctor),
    mxMarker: {
      addMarker: (type: string, funct: (...a: any[]) => any) => MarkerShape.addMarker(type, funct),
      createMarker: (...a: Parameters<typeof MarkerShape.createMarker>) => MarkerShape.createMarker(...a),
    },
    mxPoint: Point,
    mxRectangle: Rectangle,
    mxConnectionConstraint: ConnectionConstraint,
    mxPerimeter: Perimeter,
    mxStyleRegistry: StyleRegistry,
    mxEdgeStyle: EdgeStyle,
    mxStencil: StencilShape,
    mxStencilRegistry: {
      getStencil: (name: string) => StencilShapeRegistry.getStencil(name) ?? null,
      addStencil: (name: string, stencil: StencilShape) => StencilShapeRegistry.addStencil(name, stencil),
    },
    mxCellRenderer: {
      defaultShapes: CellRenderer.defaultShapes,
      registerShape(name: string, ctor: Ctor): void {
        if (appShapes?.has(name)) return;
        CellRenderer.registerShape(name, ctor as unknown as typeof Shape);
      },
      prototype: {
        getShape(name: string): any {
          const ctor = (CellRenderer.defaultShapes as unknown as Record<string, Ctor>)[name];
          return ctor != null ? es5Wrap(ctor) : null;
        },
      },
    },
    mxUtils,
    mxConstants: MX_CONSTANTS,
    mxResources: { get: (key: string, _params?: unknown, defaultValue?: string) => defaultValue ?? key },
    mxEvent: {},
    mxClient: { IS_SVG: true, IS_IE: false, IS_IE11: false, IS_FF: false, IS_SF: false, IS_GC: true },
    mxGraph: {},
    Editor: {},
    Graph: {
      createHandle: createHandleFn,
      handleFactory,
      sanitizeHtml: (html: string) => sanitizeHtmlLabel(html),
      scopeHtmlStyles,
    },
    GRAPH_IMAGE_PATH: 'img',
    lookup: (name: string) => published.get(name),
    publish: (names: Record<string, unknown>) => {
      for (const [k, v] of Object.entries(names)) published.set(k, v);
    },
  };
  return shim;
}

/** Hands the Graph.handleFactory entries a module added to the draw.io handle registry. */
export function flushHandleFactories(): number {
  if (!shim) return 0;
  const factories = shim.Graph.handleFactory as Record<string, (state: unknown) => unknown>;
  let n = 0;
  for (const name of Object.keys(factories)) {
    registerDrawioHandleFactory(name, factories[name] as never);
    delete factories[name];
    n++;
  }
  return n;
}
